class TransientError(Exception):
    pass


class PermanentError(Exception):
    pass


def _attempt(record, handler, max_attempts):
    attempts = 0
    while True:
        attempts += 1
        try:
            handler(record)
            return None, attempts
        except TransientError as e:
            if attempts >= max_attempts:
                return f"transient: {e}", attempts
        except PermanentError as e:
            return f"permanent: {e}", attempts
        except Exception as e:
            return f"unexpected: {type(e).__name__}: {e}", attempts


def process_batch(records, handler, dead_letters, max_attempts=3):
    summary = {"ok": 0, "dead": 0}
    for record in records:
        reason, attempts = _attempt(record, handler, max_attempts)
        if reason is None:
            summary["ok"] += 1
        else:
            dead_letters.append({"record": record, "reason": reason, "attempts": attempts})
            summary["dead"] += 1
    return summary


def replay(dead_letters, handler, max_attempts=3):
    remaining, fixed = [], 0
    for entry in dead_letters:
        reason, attempts = _attempt(entry["record"], handler, max_attempts)
        if reason is None:
            fixed += 1
        else:
            remaining.append({"record": entry["record"], "reason": reason, "attempts": entry["attempts"] + attempts})
    dead_letters[:] = remaining
    return fixed

