class Handler:
    def __init__(self, plan):
        self.plan = {k: list(v) for k, v in plan.items()}
        self.calls = []
    def __call__(self, record):
        self.calls.append(record)
        steps = self.plan.get(record, [])
        if steps:
            outcome = steps.pop(0)
            if outcome is not None:
                raise outcome

@test("good records pass straight through")
def _():
    dead = []
    h = Handler({})
    check_eq(process_batch(["a", "b"], h, dead), {"ok": 2, "dead": 0})
    check_eq((dead, h.calls), ([], ["a", "b"]))

@test("transient errors are retried")
def _():
    dead = []
    h = Handler({"a": [TransientError("timeout"), TransientError("timeout"), None]})
    check_eq(process_batch(["a", "b"], h, dead), {"ok": 2, "dead": 0})
    check_eq(h.calls, ["a", "a", "a", "b"])
    h = Handler({"a": [TransientError("timeout")] * 3})
    check_eq(process_batch(["a", "b"], h, dead), {"ok": 1, "dead": 1})
    check_eq(dead, [{"record": "a", "reason": "transient: timeout", "attempts": 3}])

@test("permanent and unexpected errors")
def _():
    dead = []
    h = Handler({"a": [PermanentError("422 invalid email")], "b": [KeyError("total")], "c": [TransientError("x"), PermanentError("gone")]})
    check_eq(process_batch(["a", "b", "c", "d"], h, dead), {"ok": 1, "dead": 3})
    check_eq(dead, [
        {"record": "a", "reason": "permanent: 422 invalid email", "attempts": 1},
        {"record": "b", "reason": "unexpected: KeyError: 'total'", "attempts": 1},
        {"record": "c", "reason": "permanent: gone", "attempts": 2},
    ])
    check_eq(h.calls, ["a", "b", "c", "c", "d"])

@test("replaying after a fix")
def _():
    dead = [{"record": "a", "reason": "permanent: bad", "attempts": 1},
            {"record": "b", "reason": "transient: down", "attempts": 3},
            {"record": "c", "reason": "permanent: bad", "attempts": 1}]
    h = Handler({"b": [TransientError("still down")] * 2, "c": [PermanentError("still bad")]})
    check_eq(replay(dead, h, max_attempts=2), 1)
    check_eq(dead, [{"record": "b", "reason": "transient: still down", "attempts": 5},
                    {"record": "c", "reason": "permanent: still bad", "attempts": 2}])
    check_eq(replay(dead, Handler({})), 2)
    check_eq(dead, [])

@test("an empty batch")
def _():
    dead = []
    check_eq(process_batch([], Handler({}), dead), {"ok": 0, "dead": 0})
    check_eq(replay(dead, Handler({})), 0)

